#!/usr/bin/env python3
from __future__ import annotations
import base64,re,shutil,subprocess,sys,time
from pathlib import Path

PATCH_ID="MEMEFLOW_V31_1_FITTED_REAL_WEB"
STAMP=time.strftime("%Y%m%d-%H%M%S")
JS=base64.b64decode("").decode("utf-8")

def log(x): print("[V31.1] "+str(x),flush=True)

def root():
    c=[Path.cwd(),Path.cwd()/"memeflow-app",Path.home()/"workspace",Path.home()/"workspace"/"memeflow-app",
       Path("/home/runner/workspace"),Path("/home/runner/workspace/memeflow-app"),Path("/workspace"),Path("/workspace/memeflow-app")]
    for r in c:
        try:r=r.resolve()
        except:continue
        if (r/"system.js").is_file():return r
    for b in [Path("/home/runner/workspace"),Path.cwd()]:
        if not b.exists():continue
        for p in b.glob("**/system.js"):
            if p.parent.name=="memeflow-app":return p.parent.resolve()
    raise RuntimeError("MEMEFLOW system.js not found")

ROOT=root(); SYSTEM=ROOT/"system.js"; HTML=ROOT/"system.html"
BACK=ROOT/f".v31-1-fit-backup-{STAMP}"; BACK.mkdir(parents=True,exist_ok=True)
changed=[]

def rel(p):return p.resolve().relative_to(ROOT.resolve())
def save(p):
    if p in changed:return
    d=BACK/rel(p); d.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,d); changed.append(p)
def write(p,t):save(p);p.write_text(t,encoding="utf-8");log("patched "+str(rel(p)))
def rollback(e):
    log("ERROR: "+str(e))
    for p in changed:
        b=BACK/rel(p)
        if b.exists():shutil.copy2(b,p);log("restored "+str(rel(p)))
    log("ROLLBACK COMPLETE");sys.exit(1)

def strip_v31(t):
    marker="// MEMEFLOW_V31_REAL_EVENT_WEB"; endtok="setTimeout(installRealWebV31, 1250);"
    s=t.find(marker)
    if s<0:return t,False
    e=t.find(endtok,s)
    if e<0:raise RuntimeError("old V31 marker found but end token missing; refusing unsafe delete")
    e+=len(endtok)
    return t[:s].rstrip()+"\n\n"+t[e:].lstrip(),True

try:
    t=SYSTEM.read_text(encoding="utf-8")
    if PATCH_ID in t:
        log("already installed")
    else:
        t,removed=strip_v31(t)
        if removed:log("removed old V31 visual controller")
        t=t.rstrip()+"\n\n// "+PATCH_ID+"\n"+JS+"\n"
        write(SYSTEM,t)

    if HTML.is_file():
        h=HTML.read_text(encoding="utf-8"); old=h
        h=re.sub(r'(<script[^>]+src="/system\.js)(?:\?[^"]*)?(")',r'\1?v=fit-web-v31-1\2',h,count=1)
        if h!=old:write(HTML,h)

    r=subprocess.run(["node","--check",str(SYSTEM)],cwd=ROOT,capture_output=True,text=True)
    if r.returncode:raise RuntimeError(r.stderr or r.stdout)

    s=SYSTEM.read_text(encoding="utf-8")
    for token in [PATCH_ID,"MF_LAYOUT_MOBILE_V311","mfFitCameraV311","new THREE.Box3()","mfBuildWebV311","mfShootV311","MEMEFLOW_V31_1_END"]:
        if token not in s:raise RuntimeError("validation missing: "+token)
    if "const REAL_WEB_V31 =" in s:raise RuntimeError("old V31 controller still present")

    log("system.js syntax OK")
    srv=ROOT/"app-server.mjs"
    if srv.is_file() and "/api/system/stream" in srv.read_text(encoding="utf-8"):log("real System SSE detected")
    else:log("WARNING: System SSE not found; telemetry fallback will be used")

    log("INSTALL COMPLETE")
    log("backup: "+str(BACK))
    log("X/Z floor topology + Box3 auto-fit enabled")
    log("all 10 blocks fit home view; pinch/zoom/rotate preserved")
    log("multi-strand web + fast thread shots enabled")
    log("restart app/workflow and hard-refresh Safari")
except Exception as e:
    rollback(e)
